# Deliberately separate single-token entries from multiword phrases:
# multiword expressions cannot be safely treated as single POS tokens.
def base_lexicon():
    result = {}
    for tag, text in CURATED.items():
        # This block is token-level vocabulary. Multiword phrases must be reviewed
        # separately and are not represented by whitespace-joined tokens here.
        for token in text.split():
            result.setdefault(token, tag)
    return result


def expand_existing(existing):
    """Preserve prior lexicon and add curated candidates without overwriting tags."""
    merged = dict(existing)
    conflicts=[]
    for tag, text in CURATED.items():
        for token in text.split():
            if token in merged and merged[token] != tag:
                conflicts.append((token, merged[token], tag))
            else:
                merged[token]=tag
    return merged, conflicts


def audit(lexicon):
    counts=Counter(lexicon.values())
    return {tag: {'count':counts[tag], 'missing':max(0,200-counts[tag])} for tag in CURATED}


def export_candidate_review(existing, articles, output_path):
    """Export proposed new entries for human approval with corpus frequencies."""
    all_counts=Counter()
    for article in articles.values():
        all_counts.update(article.split())
    rows=[]
    for tag,text in CURATED.items():
        for token in sorted(set(text.split())):
            if token in existing:
                continue
            rows.append((token,tag,all_counts[token],''))
    rows.sort(key=lambda row:(row[1],-row[2],row[0]))
    output_path=Path(output_path)
    output_path.parent.mkdir(parents=True,exist_ok=True)
    with output_path.open('w',encoding='utf-8-sig',newline='') as f:
        w=csv.writer(f)
        w.writerow(['token','suggested_pos','corpus_frequency','verified_pos'])
        w.writerows(rows)
    return len(rows)


def apply_verified_review(existing, csv_path):
    """Import only rows whose verified_pos column was explicitly filled."""
    merged=dict(existing)
    with Path(csv_path).open(encoding='utf-8-sig',newline='') as f:
        for row in csv.DictReader(f):
            token=row['token'].strip()
            tag=row['verified_pos'].strip().upper()
            if not tag:
                continue
            if tag not in CURATED:
                raise ValueError(f'Unexpected tag {tag!r} for {token!r}')
            if token in merged and merged[token]!=tag:
                raise ValueError(f'Conflicting reviewed POS for {token}')
            merged[token]=tag
    return merged
